    public static int stCircle(emon.Port.Cells pa, emon.Port.Cells pts, int page, int cx, int cy, int stroke, int width, int skew) {
        // A stroked, unfilled path of eight Bezier segments whose end points lie on a circle of radius 3000 about (cx, cy) (the control points on the chord ends);
        // `skew` moves the third end point sideways by that much, which spoils the roundness. Answers the path's row.
        int first = emon.Port.cellsLen(pts) / 3;
        int k = 0;
        int x = 0;
        int y = 0;
        int r = Evidence.paNew(pa, page, Evidence.paCurve(), cx - 3000, cy - 3000, cx + 3000, cy + 3000);
        Evidence.ptAdd(pts, cx + stEx(0), cy + stEy(0), Evidence.poMove());
        while (k < 8) {
            x = cx + stEx(k + 1);
            y = cy + stEy(k + 1);
            if (k == 2) {
                x += skew;
            }
            Evidence.ptAdd(pts, cx + stEx(k), cy + stEy(k), Evidence.poCurve());
            Evidence.ptAdd(pts, x, y, Evidence.poCurve());
            Evidence.ptAdd(pts, x, y, Evidence.poCurve());
            k += 1;
        }
        Evidence.ptAdd(pts, cx + stEx(0), cy + stEy(0), Evidence.poClose());
        Evidence.paSet(pa, r, Evidence.pfFlags(), Evidence.pgStroked());
        Evidence.paSet(pa, r, Evidence.pfStroke(), stroke);
        Evidence.paSet(pa, r, Evidence.pfWidth(), width);
        Evidence.paSet(pa, r, Evidence.pfPfirst(), first);
        Evidence.paSet(pa, r, Evidence.pfPcount(), 26);
        return r;
    }
