    public static int stStroke(emon.Port.Cells pa, emon.Port.Cells pts, int x0, int y0, int segs) {
        // An open stroked curve of `segs` Bezier segments from (x0, y0), 800 wide each and 1500 high; answers its row.
        int first = emon.Port.cellsLen(pts) / 3;
        int k = 0;
        int r = Evidence.paNew(pa, 1, Evidence.paCurve(), x0, y0, x0 + (segs * 800), y0 + 1500);
        Evidence.ptAdd(pts, x0, y0, Evidence.poMove());
        while (k < segs) {
            Evidence.ptAdd(pts, x0 + (k * 800), y0 + 1500, Evidence.poCurve());
            Evidence.ptAdd(pts, x0 + (k * 800) + 400, y0, Evidence.poCurve());
            Evidence.ptAdd(pts, x0 + ((k + 1) * 800), y0 + 700, Evidence.poCurve());
            k += 1;
        }
        Evidence.paSet(pa, r, Evidence.pfFlags(), Evidence.pgStroked());
        Evidence.paSet(pa, r, Evidence.pfStroke(), 2047903);
        Evidence.paSet(pa, r, Evidence.pfWidth(), 140);
        Evidence.paSet(pa, r, Evidence.pfPfirst(), first);
        Evidence.paSet(pa, r, Evidence.pfPcount(), 1 + (segs * 3));
        return r;
    }
